SetFunctionName("Mask2 CompLessThan(Vector2 a, Vector2 b)");
Vector2 va1(1.0f, 1.0f);
Vector2 va2(2.0f, 2.0f );
Vector2 vb1(1.0f, 2.0f);
Vector2 vb2(1.0f, -1.0f );

Mask2 mask1(CompLessThan(va1, vb1));
Mask2 mask2(CompLessThan(va2, vb2));
Validate(
    !mask1.GetX().GetBool() &&
     mask1.GetY().GetBool() &&
    !mask2.GetX().GetBool() &&
    !mask2.GetY().GetBool()
);



SetFunctionName("Mask2 CompGreaterThan(Vector2 a, Vector2 b)");
