Vector2 vb1(1.0f, 2.0f);
Vector2 vb2(1.0f, -1.0f );

Mask2 mask1(CompGreaterThan(va1, vb1));
Mask2 mask2(CompGreaterThan(va2, vb2));
Validate(
    !mask1.GetX().GetBool() &&
    !mask1.GetY().GetBool() &&
     mask2.GetX().GetBool() &&
     mask2.GetY().GetBool()
);



