SetFunctionName("Vector2 Select(MaskScalar mask, Vector2 a, Vector2 b)");
Vector2 v1a(1.0f, 2.0f);
Vector2 v1b(3.0f, 4.0f);
Vector2 v2a(10.0f, 20.0f);
Vector2 v2b(30.0f, 40.0f);

Vector2 result1a = Select( MaskScalar(true), v1a, v2a );
Vector2 result1b = Select( MaskScalar(true), v1b, v2b );
Vector2 result2a = Select( MaskScalar(false), v1a, v2a );
Vector2 result2b = Select( MaskScalar(false), v1b, v2b );
Validate(
    result1a == v1a &&
    result2a == v2a &&
    result1b == v1b &&
    result2b == v2b
);


#ifdef HOST_TESTING
        SetFunctionName("Vector2 Select(MaskScalar mask, Vector2 a, Vector2 b)");
