SetFunctionName("Vector2 Select(Mask2 mask, Vector2 a, Vector2 b)");
Vector2 v1a(1.0f, 2.0f);
Vector2 v1b(3.0f, 4.0f);
Vector2 v2a(10.0f, 20.0f);
Vector2 v2b(30.0f, 40.0f);
Vector2 ref1a(1.0f, 2.0f);
Vector2 ref1b(30.0f, 40.0f);
Vector2 ref2a(10.0f, 20.0f);
Vector2 ref2b(3.0f, 4.0f);
Mask2 mask1a(true, true);
Mask2 mask1b(false, false);
Mask2 mask2a(false, false);
Mask2 mask2b(true, true);

Vector2 result1a = Select( mask1a, v1a, v2a );
Vector2 result1b = Select( mask1b, v1b, v2b );
Vector2 result2a = Select( mask2a, v1a, v2a );
Vector2 result2b = Select( mask2b, v1b, v2b );
Validate(
    result1a == ref1a &&
    result1b == ref1b &&
    result2a == ref2a &&
    result2b == ref2b
);



SetFunctionName("Vector2 ClampToNegPosRange(value, range)");
Vector2 range(5.0f,  5.0f);
Vector2   v1( 7.0f,  3.0f);
Vector2   v2(-7.0f, -3.0f);
Vector2 ref1( 5.0f,  3.0f);
Vector2 ref2(-5.0f, -3.0f);
Vector2 result1 = ClampToNegPosRange( v1, range );
Vector2 result2 = ClampToNegPosRange( v2, range );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector2 Permute<pattern>(value)");
Vector2 v(1.0f, 2.0f);
Vector2 ref1( 2.0f, 1.0f );
Vector2 ref2( 1.0f, 1.0f );
Vector2 result1 = Permute<0x10>(v);
Vector2 result2 = Permute<0x00>(v);
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector2 unaligned load/store tests");
float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = static_cast<float>(i+1);

::rw::math::fpu::Vector2Template<float>* alignedVec = reinterpret_cast< ::rw::math::fpu::Vector2Template<float>*>(&buffer[0]);
Vector2 v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 1.0f && v.Y() == 2.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector2Template<float>*>(&buffer[1]);        
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 2.0f && v.Y() == 3.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector2Template<float>*>(&buffer[2]);        
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 3.0f && v.Y() == 4.0f);        

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector2Template<float>*>(&buffer[3]);         
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 4.0f && v.Y() == 5.0f);



SetFunctionName("Vector2 unaligned store tests");

float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = 0.0f;

Vector2 v2;

v2.Set(1.1f, 2.2f);
::rw::math::fpu::Vector2* unaligned = reinterpret_cast< ::rw::math::fpu::Vector2*>(&buffer[0]);        
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[0] == 1.1f && buffer[1] == 2.2f && buffer[2] == 0 && buffer[3] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector2*>(&buffer[1]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[1] == 1.1f && buffer[2] == 2.2f && buffer[3] == 0 && buffer[4] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector2*>(&buffer[2]);        
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[2] == 1.1f && buffer[3] == 2.2f && buffer[4] == 0 && buffer[5] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector2*>(&buffer[3]);        
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[3] == 1.1f && buffer[4] == 2.2f && buffer[5] == 0 && buffer[6] == 0);



