output = Negate(v2a);
Validate(IsEqualWithEpsilon((float_basic_type)v2a.X(), (float_basic_type)-output.X()) && IsEqualWithEpsilon((float_basic_type)v2a.Y(), (float_basic_type)-output.Y()));



Vector2 v2a, v2b, output;
v2a.Set(1.0f, 2.0f);
v2b.Set(3.0f, 4.0f);
