Vector2 v2a, output;

float_test_type fResult;
bool success = true;
SetFunctionName("CheckedNormalizeReturnMagnitude(const Vector2 &v, Vector2 &result)");

v2a.Set(1.0f, 2.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v2a, output);
success &= IsEqualWithEpsilon(output.X(), (float_test_type)0.44721359f);
success &= IsEqualWithEpsilon(output.Y(), (float_test_type)0.89442711f);
success &= IsEqualWithEpsilon(fResult, (float_test_type)2.23606798f);

v2a.Set(0.0f, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v2a, output);
success &= IsEqualWithEpsilon((float)output.X(), 0.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_test_type)0.0f);

v2a.Set(SMALL_FLOAT, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v2a, output);
success &= IsEqualWithEpsilon((float)output.X(), 1.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_test_type)0.0f);

v2a.Set(MIN_FLOAT, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v2a, output);
// Two solutions are acceptable depending on the precision that
// calculations are carried out with.  Either the magnitude appears to
// be zero (e.g. for 32bit calculations), or the magnitude appears to
// be a very small number (i.e. MIN_FLOAT).
// The result vector will then be 0 (if magnitude is zero), or the X
// axis otherwise.
success &= IsEqualWithEpsilon((float)output.X(), 0.0f) || IsEqualWithEpsilon((float)output.X(), 1.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_test_type)0.0f) || IsEqualWithEpsilon(fResult, (float_test_type)MIN_FLOAT);

Validate(success);



