SetFunctionName("Vector2 RotateLeft(Vector2 v2)");

float_basic_type values[] = { 1.0f, 2.0f };
#ifdef HOST_TESTING
    // We want to make sure that the z/w element in the vector aren't the same as X and Y.  Otherwise a rotate could appear to work due to how a Vector2 is initialized.
    MakeVectorIntrinsic(vi, 1.0f, 2.0f, 0.0f, 0.0f);
    Vector2 v2(vi);
#else
    Vector2 v2(values[0], values[1]);
#endif
Vector2 v2r = RotateLeft(v2);
Validate( 
    v2r.X() == (float_test_type)values[1] &&
    v2r.Y() == (float_test_type)values[0]
);



